insert into public.countries (iso2,name,phone_code) values ('IN','India','+91'),('PK','Pakistan','+92'),('BD','Bangladesh','+880'),('AE','United Arab Emirates','+971'),('SA','Saudi Arabia','+966'),('GB','United Kingdom','+44'),('US','United States','+1'),('CA','Canada','+1'),('AU','Australia','+61') on conflict (iso2) do update set name=excluded.name, phone_code=excluded.phone_code;
insert into public.states(country_id,code,name) select c.id,v.code,v.name from public.countries c cross join (values ('MH','Maharashtra'),('DL','Delhi'),('KA','Karnataka'),('TG','Telangana'),('TN','Tamil Nadu'),('GJ','Gujarat'),('UP','Uttar Pradesh'),('WB','West Bengal'),('KL','Kerala'),('RJ','Rajasthan')) v(code,name) where c.iso2='IN' on conflict(country_id,code) do update set name=excluded.name;
insert into public.cities(state_id,name,latitude,longitude) select s.id,v.name,v.lat,v.lng from public.states s join public.countries c on c.id=s.country_id join (values ('MH','Mumbai',19.0760,72.8777),('MH','Pune',18.5204,73.8567),('DL','New Delhi',28.6139,77.2090),('KA','Bengaluru',12.9716,77.5946),('TG','Hyderabad',17.3850,78.4867),('TN','Chennai',13.0827,80.2707),('GJ','Ahmedabad',23.0225,72.5714),('UP','Lucknow',26.8467,80.9462),('WB','Kolkata',22.5726,88.3639),('KL','Kochi',9.9312,76.2673),('RJ','Jaipur',26.9124,75.7873)) v(state_code,name,lat,lng) on s.code=v.state_code where c.iso2='IN' on conflict(state_id,name) do nothing;
