insert into public.subscription_plans(code,name,price_minor,currency,interval_months,features) values ('free','Free',0,'INR',1,'{"interests_per_month":20,"advanced_search":false}'::jsonb),('premium_monthly','Premium Monthly',99900,'INR',1,'{"unlimited_interests":true,"advanced_search":true,"read_receipts":true}'::jsonb),('premium_quarterly','Premium Quarterly',249900,'INR',3,'{"unlimited_interests":true,"advanced_search":true,"read_receipts":true}'::jsonb) on conflict(code) do update set name=excluded.name,price_minor=excluded.price_minor,features=excluded.features;
